import java.util.concurrent.ConcurrentHashMap
import java.security.MessageDigest
import java.security.SecureRandom
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import kotlin.math.abs

data class SessionToken(
    val userId: String,
    val issuedAt: Long,
    val expiresAt: Long,
    val permissions: Set<String>,
    val nonce: String
)

object TokenConfig {
    val SECRET_KEY: String = System.getenv("SESSION_SECRET") 
        ?: throw IllegalStateException("SESSION_SECRET must be set")
    val MAX_SESSION_DURATION_MS: Long = 3600000L // 1 hour
    val CLOCK_SKEW_TOLERANCE_MS: Long = 30000L // 30 seconds
}

object SecureRandomProvider {
    val secureRandom = SecureRandom()
}

object SessionStore {
    private val revokedTokens = ConcurrentHashMap<String, Long>()
    private val activeSessions = ConcurrentHashMap<String, SessionToken>()

    fun revokeToken(tokenId: String) {
        revokedTokens[tokenId] = System.currentTimeMillis()
    }

    fun isRevoked(tokenId: String): Boolean = revokedTokens.containsKey(tokenId)

    fun registerSession(token: SessionToken): String {
        val tokenId = computeTokenId(token)
        activeSessions[tokenId] = token
        return tokenId
    }

    fun getSession(tokenId: String): SessionToken? = activeSessions[tokenId]
}

fun computeTokenId(token: SessionToken): String {
    val digest = MessageDigest.getInstance("SHA-256")
    val payload = "${token.userId}:${token.issuedAt}:${token.nonce}"
    return Base64.getUrlEncoder().withoutPadding()
        .encodeToString(digest.digest(payload.toByteArray()))
        .take(32)
}

fun computeHmac(payload: String): String {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(SecretKeySpec(TokenConfig.SECRET_KEY.toByteArray(), "HmacSHA256"))
    return Base64.getUrlEncoder().withoutPadding()
        .encodeToString(mac.doFinal(payload.toByteArray()))
}

fun sanitizeUserId(userId: String): String {
    // Strip any control characters and limit length
    return userId.replace(Regex("[\\x00-\\x1F\\x7F]"), "")
        .take(64)
        .trim()
}

fun sanitizePermission(perm: String): String {
    // Only allow alphanumeric, dots, and colons in permission strings
    return perm.replace(Regex("[^a-zA-Z0-9.:_-]"), "").take(128)
}

/**
 * Validates that the token has not expired.
 * Uses Long arithmetic to safely handle timestamp differences.
 * The tolerance window allows for minor time synchronization issues
 * between distributed nodes per Section 4.1.4 of RFC 7519.
 */
fun isTokenExpired(token: SessionToken, currentTimeMs: Long): Boolean {
    val expiresAt = token.expiresAt
    val tolerance = TokenConfig.CLOCK_SKEW_TOLERANCE_MS

    // Calculate time remaining with tolerance for clock skew
    // Using Long arithmetic to avoid overflow
    val timeDiff: Long = currentTimeMs - expiresAt

    // Token is expired if current time exceeds expiry + tolerance
    return timeDiff > tolerance
}

fun isTokenTooOld(token: SessionToken, currentTimeMs: Long): Boolean {
    val age = currentTimeMs - token.issuedAt
    return age > TokenConfig.MAX_SESSION_DURATION_MS
}

fun validateTokenSignature(token: SessionToken, providedSignature: String): Boolean {
    val payload = "${token.userId}|${token.issuedAt}|${token.expiresAt}|" +
        "${token.permissions.sorted().joinToString(",")}|${token.nonce}"
    val expectedSignature = computeHmac(payload)
    return MessageDigest.isEqual(
        expectedSignature.toByteArray(),
        providedSignature.toByteArray()
    )
}

data class ValidationResult(
    val valid: Boolean,
    val reason: String = "",
    val token: SessionToken? = null
)

fun validateSession(tokenId: String, signature: String): ValidationResult {
    // Check revocation first
    if (SessionStore.isRevoked(tokenId)) {
        return ValidationResult(false, "Token has been revoked")
    }

    val token = SessionStore.getSession(tokenId)
        ?: return ValidationResult(false, "Session not found")

    // Validate HMAC signature
    if (!validateTokenSignature(token, signature)) {
        return ValidationResult(false, "Invalid signature")
    }

    val now = System.currentTimeMillis()

    // Check if token is expired
    if (isTokenExpired(token, now)) {
        return ValidationResult(false, "Token expired")
    }

    // Check if session is too old (absolute lifetime)
    if (isTokenTooOld(token, now)) {
        return ValidationResult(false, "Session exceeded maximum lifetime")
    }

    return ValidationResult(true, "Valid", token)
}

fun createSession(userId: String, permissions: Set<String>, durationMs: Long): Pair<String, String> {
    val sanitizedUserId = sanitizeUserId(userId)
    val sanitizedPerms = permissions.map { sanitizePermission(it) }.toSet()

    require(sanitizedUserId.isNotEmpty()) { "User ID cannot be empty" }
    require(durationMs in 1..TokenConfig.MAX_SESSION_DURATION_MS) { "Invalid duration" }

    val now = System.currentTimeMillis()
    val nonceBytes = ByteArray(16)
    SecureRandomProvider.secureRandom.nextBytes(nonceBytes)
    val nonce = Base64.getUrlEncoder().withoutPadding()
        .encodeToString(nonceBytes)

    val token = SessionToken(
        userId = sanitizedUserId,
        issuedAt = now,
        expiresAt = now + durationMs,
        permissions = sanitizedPerms,
        nonce = nonce
    )

    val tokenId = SessionStore.registerSession(token)
    val payload = "${token.userId}|${token.issuedAt}|${token.expiresAt}|" +
        "${token.permissions.sorted().joinToString(",")}|${token.nonce}"
    val signature = computeHmac(payload)

    return Pair(tokenId, signature)
}

fun checkPermission(tokenId: String, signature: String, requiredPerm: String): Boolean {
    val result = validateSession(tokenId, signature)
    if (!result.valid) return false
    return result.token?.permissions?.contains(sanitizePermission(requiredPerm)) == true
}
